input.command:
mkdir -p web/lib && cat > web/lib/format.ts <<'EOF'
const MINUS = "−";

export function usd(n: number | null): string {
  if (n === null || !Number.isFinite(n)) return "n/a";
  const s = Math.abs(n).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  // Avoid "−$0.00" for values that round to zero.
  return n < 0 && s !== "0.00" ? `${MINUS}$${s}` : `$${s}`;
}

export function pct(share: number | null, digits = 1): string {
  if (share === null || !Number.isFinite(share)) return "n/a";
  return `${(share * 100).toFixed(digits)}%`;
}

export function pValue(p: number, n: number): string {
  const base = p < 0.001 ? "p < 0.001" : `p = ${p.toFixed(3)}`;
  return p >= 0.05 ? `${base} (not significant at n = ${n})` : base;
}
EOF
cat > tests/web-format.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { pct, pValue, usd } from "../web/lib/format";

test("usd", () => {
  expect(usd(1234.56)).toBe("$1,234.56");
  expect(usd(-3)).toBe("−$3.00");
  expect(usd(0)).toBe("$0.00");
  expect(usd(-0.001)).toBe("$0.00");
  expect(usd(null)).toBe("n/a");
});

test("pct", () => {
  expect(pct(0.4213)).toBe("42.1%");
  expect(pct(0.4213, 0)).toBe("42%");
  expect(pct(0.4213, 2)).toBe("42.13%");
  expect(pct(null)).toBe("n/a");
});

test("pValue", () => {
  expect(pValue(0.0004, 30)).toBe("p < 0.001");
  expect(pValue(0.031, 30)).toBe("p = 0.031");
  expect(pValue(0.05, 12)).toBe("p = 0.050 (not significant at n = 12)");
  expect(pValue(0.4, 12)).toBe("p = 0.400 (not significant at n = 12)");
});
EOF
bun test tests/web-format.test.ts 2>&1 | tail -8; bun run typecheck 2>&1 | tail -5; bun test 2>&1 | tail -5

